	bucket := m.buckets[idx]
	// 遍历桶，若找到 key ，则返回对应 val
	for _, p := range bucket {
		if p.key == key {
			return p.val
		}
	}
	// 若未找到 key ，则返回空字符串
	return ""
}

/* 添加操作 */
