package chapter_hashing

import (
	"fmt"
)

/* 开放寻址哈希表 */
type hashMapOpenAddressing struct {
	size        int     // 键值对数量
	capacity    int     // 哈希表容量
	loadThres   float64 // 触发扩容的负载因子阈值
	extendRatio int     // 扩容倍数
	buckets     []*pair // 桶数组
	TOMBSTONE   *pair   // 删除标记
}

/* 构造方法 */
func newHashMapOpenAddressing() *hashMapOpenAddressing {
	return &hashMapOpenAddressing{
		size:        0,
		capacity:    4,
		loadThres:   2.0 / 3.0,
		extendRatio: 2,
		buckets:     make([]*pair, 4),
		TOMBSTONE:   &pair{-1, "-1"},
	}
}

/* 哈希函数 */
func (h *hashMapOpenAddressing) hashFunc(key int) int {
	return key % h.capacity // 根据键计算哈希值
}

/* 负载因子 */
func (h *hashMapOpenAddressing) loadFactor() float64 {
	return float64(h.size) / float64(h.capacity) // 计算当前负载因子
}

/* 搜索 key 对应的桶索引 */
func (h *hashMapOpenAddressing) findBucket(key int) int {
	index := h.hashFunc(key) // 获取初始索引
	firstTombstone := -1     // 记录遇到的第一个TOMBSTONE的位置
	for h.buckets[index] != nil {
		if h.buckets[index].key == key {
			if firstTombstone != -1 {
				// 若之前遇到了删除标记，则将键值对移动至该索引处
				h.buckets[firstTombstone] = h.buckets[index]
				h.buckets[index] = h.TOMBSTONE
				return firstTombstone // 返回移动后的桶索引
			}
			return index // 返回找到的索引
		}
		if firstTombstone == -1 && h.buckets[index] == h.TOMBSTONE {
			firstTombstone = index // 记录遇到的首个删除标记的位置
		}
		index = (index + 1) % h.capacity // 线性探测，越过尾部则返回头部
	}
	// 若 key 不存在，则返回添加点的索引
	if firstTombstone != -1 {
		return firstTombstone
	}
	return index
}

/* 查询操作 */
func (h *hashMapOpenAddressing) get(key int) string {
	index := h.findBucket(key) // 搜索 key 对应的桶索引
