    int index = findBucket(key);
    // 若找到键值对，则覆盖 val 并返回
    if (_buckets[index] != null && _buckets[index] != _TOMBSTONE) {
      _buckets[index]!.val = val;
      return;
    }
    // 若键值对不存在，则添加该键值对
    _buckets[index] = new Pair(key, val);
    _size++;
  }

  /* 删除操作 */
  void remove(int key) {
    // 搜索 key 对应的桶索引
    int index = findBucket(key);
    // 若找到键值对，则用删除标记覆盖它
    if (_buckets[index] != null && _buckets[index] != _TOMBSTONE) {
      _buckets[index] = _TOMBSTONE;
      _size--;
    }
  }

  /* 扩容哈希表 */
  void extend() {
    // 暂存原哈希表
    List<Pair?> bucketsTmp = _buckets;
    // 初始化扩容后的新哈希表
    _capacity *= _extendRatio;
    _buckets = List.generate(_capacity, (index) => null);
    _size = 0;
    // 将键值对从原哈希表搬运至新哈希表
    for (Pair? pair in bucketsTmp) {
      if (pair != null && pair != _TOMBSTONE) {
        put(pair.key, pair.val);
      }
    }
  }

  /* 打印哈希表 */
  void printHashMap() {
    for (Pair? pair in _buckets) {
      if (pair == null) {
        print("null");
      } else if (pair == _TOMBSTONE) {
        print("TOMBSTONE");
      } else {
        print("${pair.key} -> ${pair.val}");
      }
    }
  }
}

/* Driver Code */
void main() {
  /* 初始化哈希表 */
  HashMapOpenAddressing map = HashMapOpenAddressing();

  /* 添加操作 */
  // 在哈希表中添加键值对 (key, value)
  map.put(12836, "小哈");
  map.put(15937, "小啰");
  map.put(16750, "小算");
  map.put(13276, "小法");
  map.put(10583, "小鸭");
  print("\n添加完成后，哈希表为\nKey -> Value");
  map.printHashMap();

  /* 查询操作 */
  // 向哈希表中输入键 key ，得到值 value
  String? name = map.get(13276);
  print("\n输入学号 13276 ，查询到姓名 $name");

  /* 删除操作 */
  // 在哈希表中删除键值对 (key, value)
  map.remove(16750);
  print("\n删除 16750 后，哈希表为\nKey -> Value");
  map.printHashMap();
}
